#[Route('/api/transfers', methods: ['POST'])]
#[IsGranted('ROLE_USER')]
public function create(
    #[MapRequestPayload] TransferRequest $dto,
    Request $request,
    IdempotencyGuard $guard,
    TransferService $transfers,
): JsonResponse {
    $key = (string) $request->headers->get('Idempotency-Key');
    if (!Uuid::isValid($key)) {
        throw new BadRequestHttpException('Idempotency-Key header must be a UUID');
    }

    $hash = hash('sha256', implode('|', [
        $request->getMethod(), $request->getPathInfo(), $request->getContent(),
    ]));

    return $guard->run(
        scope: 'user:'.$this->getUser()->getUserIdentifier(),
        key: $key,
        hash: $hash,
        work: fn () => $this->json($transfers->send($dto), 201),
    );
}

final readonly class IdempotencyGuard
{
    public function __construct(private Connection $db) {}

    /** @param \Closure(): JsonResponse $work */
    public function run(string $scope, string $key, string $hash, \Closure $work): JsonResponse
    {
        return $this->db->transactional(function () use ($scope, $key, $hash, $work) {
            $claimed = $this->db->executeStatement(
                'INSERT INTO idempotency_key (scope, idem_key, fingerprint, created_at)
                 VALUES (?, ?, ?, now()) ON CONFLICT (scope, idem_key) DO NOTHING',
                [$scope, $key, $hash],
            );
            if (0 === $claimed) {
                return $this->replay($scope, $key, $hash);   // key seen before
            }
            $response = $work();                             // the real work, once
            $this->db->update('idempotency_key', [
                'response_status' => $response->getStatusCode(),
                'response_body' => $response->getContent(),
            ], ['scope' => $scope, 'idem_key' => $key]);
            return $response;
        });
    }

    private function replay(string $scope, string $key, string $hash): JsonResponse
    {
        $row = $this->db->fetchAssociative('SELECT fingerprint, response_status, response_body
            FROM idempotency_key WHERE scope = ? AND idem_key = ?', [$scope, $key]);
        if (!hash_equals($row['fingerprint'], $hash)) {
            throw new UnprocessableEntityHttpException('Same key, different request');
        }
        return JsonResponse::fromJsonString(
            $row['response_body'], (int) $row['response_status']);
    }
}

