final readonly class WebhookVerifier
{
    public function __construct(
        #[Autowire('%env(PAY_WEBHOOK_SECRET)%')] private string $secret,
        private ClockInterface $clock,
    ) {}

    public function verify(string $rawBody, string $header): void
    {
        parse_str(str_replace(',', '&', $header), $parts);   // t=...,v1=...
        $t = (int) ($parts['t'] ?? 0);
        $sig = (string) ($parts['v1'] ?? '');

        if (abs($this->clock->now()->getTimestamp() - $t) > 300) {
            throw new BadRequestHttpException('Timestamp too old');
        }
        $expected = hash_hmac('sha256', $t.'.'.$rawBody, $this->secret);
        if (!hash_equals($expected, $sig)) {
            throw new AccessDeniedHttpException('Signature mismatch');
        }
    }
}

#[Route('/webhooks/pay', methods: ['POST'])]
public function __invoke(
    Request $request,
    WebhookVerifier $verifier,
    MessageBusInterface $bus,
    Connection $db,
): Response {
    $raw = $request->getContent();                 // raw body, before json_decode
    $verifier->verify($raw, (string) $request->headers->get('X-Signature'));
    $event = json_decode($raw, true, flags: JSON_THROW_ON_ERROR);

    $db->executeStatement(
        'INSERT INTO webhook_event (event_id, type, payload, received_at)
         VALUES (?, ?, ?, now()) ON CONFLICT (event_id) DO NOTHING',
        [$event['id'], $event['type'], $raw],
    );
    $bus->dispatch(new ProcessWebhookEvent($event['id']));

    return new Response('', 200);                  // no slow work here
}

