#[AsMessageHandler]
final readonly class ProcessWebhookEventHandler
{
    public function __construct(private Connection $db, private PaymentService $payments) {}

    public function __invoke(ProcessWebhookEvent $m): void
    {
        $this->db->transactional(function () use ($m): void {
            $claimed = $this->db->executeStatement(
                'UPDATE webhook_event SET processed_at = now()
                 WHERE event_id = ? AND processed_at IS NULL',
                [$m->eventId],
            );
            if (0 === $claimed) {
                return;                    // already done: a duplicate
            }
            $payload = $this->db->fetchOne(
                'SELECT payload FROM webhook_event WHERE event_id = ?', [$m->eventId]);
            $event = json_decode($payload, true);
            $outcome = $this->payments->applyGatewayEvent(
                $event['data']['id'], $event['type']);
            if (Outcome::TooEarly === $outcome) {
                throw new EventTooEarly($m->eventId);   // rolls back the claim
            }
        });
    }
}

enum Outcome { case Applied; case Stale; case TooEarly; }

private const RANK = ['created' => 0, 'pending' => 1,
    'succeeded' => 2, 'failed' => 2, 'refunded' => 3];

public function applyGatewayEvent(string $gatewayId, string $type): Outcome
{
    $payment = $this->repo->findOneBy(['gatewayId' => $gatewayId]);
    if (null === $payment) {
        return Outcome::TooEarly;            // no row has this gateway id yet
    }
    [$transition, $target] = match ($type) {
        'payment.succeeded' => ['succeed', 'succeeded'],
        'payment.failed' => ['fail', 'failed'],
        'payment.refunded' => ['refund', 'refunded'],
        default => [null, null],             // a type we do not act on
    };
    if (null === $transition) {
        return Outcome::Stale;
    }
    if ($this->transitions->apply($payment->getId(), $transition)) {
        return Outcome::Applied;
    }
    // Not legal now: is the payment behind the event, or already past it?
    return self::RANK[$payment->getStatus()] < self::RANK[$target]
        ? Outcome::TooEarly
        : Outcome::Stale;
}

framework:
    workflows:
        payment:
            type: state_machine
            audit_trail: {enabled: true}
            marking_store: {type: method, property: status}
            supports: [App\Entity\Payment]
            initial_marking: created
            places: [created, pending, succeeded, failed, refunded]
            transitions:
                submit:  {from: created,   to: pending}
                succeed: {from: pending,   to: succeeded}
                fail:    {from: pending,   to: failed}
                refund:  {from: succeeded, to: refunded}

final readonly class PaymentTransitions
{
    public function __construct(private WorkflowInterface $paymentStateMachine) {}

    public function apply(Payment $payment, string $transition): bool
    {
        if (!$this->paymentStateMachine->can($payment, $transition)) {
            return false;                    // not legal right now
        }
        $this->paymentStateMachine->apply($payment, $transition);

        return true;
    }
}

