if ($this->paymentStateMachine->can($payment, 'fail')) {
    $this->paymentStateMachine->apply($payment, 'fail');
    $em->flush();                                    // the last writer wins
}

public function apply(int $id, string $transition): bool
{
    return $this->em->wrapInTransaction(function () use ($id, $transition): bool {
        $payment = $this->em->find(Payment::class, $id, LockMode::PESSIMISTIC_WRITE);

        if (!$this->paymentStateMachine->can($payment, $transition)) {
            return false;                  // someone else got there first
        }
        $this->paymentStateMachine->apply($payment, $transition);
        $this->em->persist(new PaymentLog($payment, $transition));

        return true;                       // wrapInTransaction flushes here
    });
}

