public function charge(Payment $payment): void
{
    $this->transitions->apply($payment->getId(), 'submit');   // pending first, commit
    try {
        $res = $this->gateway->request('POST', '/charges', [
            'headers' => ['Idempotency-Key' => $payment->getIdempotencyKey()],
            'json' => [
                'reference' => $payment->getReference(),
                'amount' => $payment->getAmount(),
            ],
            'timeout' => 5,
        ]);
        $code = $res->getStatusCode();
    } catch (TransportExceptionInterface) {       // timeout or dropped: outcome unknown
        $this->checkLater($payment);
        return;
    }
    match (true) {
        $code < 300 => $this->transitions->apply($payment->getId(), 'succeed'),
        $code === 408 || $code === 429 || $code >= 500 => $this->checkLater($payment),
        default => $this->transitions->apply($payment->getId(), 'fail'),   // a clear no
    };
}

private function checkLater(Payment $payment): void
{
    $this->bus->dispatch(
        new CheckPaymentStatus($payment->getId()), [new DelayStamp(30_000)]);
}

public function __invoke(CheckPaymentStatus $m): void
{
    $payment = $this->repo->find($m->paymentId);
    if ('pending' !== $payment->getStatus()) {
        return;                                   // a webhook already settled it
    }
    $res = $this->gateway->request('GET', '/charges', [
        'query' => ['reference' => $payment->getReference()],
    ]);
    if (404 === $res->getStatusCode()) {
        $this->bus->dispatch(new RetryCharge($payment->getId()));   // same key
        return;                                   // the gateway never got the call
    }
    match ($res->toArray()['status']) {
        'succeeded' => $this->transitions->apply($payment->getId(), 'succeed'),
        'failed' => $this->transitions->apply($payment->getId(), 'fail'),
        default => $this->bus->dispatch(          // still in progress: ask again
            new CheckPaymentStatus($payment->getId()), [new DelayStamp(60_000)]),
    };
}

#[AsPeriodicTask(frequency: '10 minutes', schedule: 'default')]
final readonly class StalePendingSweeper
{
    public function __construct(private Connection $db, private MessageBusInterface $bus) {}

    public function __invoke(): void
    {
        $ids = $this->db->fetchFirstColumn(
            "SELECT id FROM payment
             WHERE status = 'pending' AND updated_at < now() - interval '15 minutes'"
        );
        foreach ($ids as $id) {
            $this->bus->dispatch(new CheckPaymentStatus((int) $id));
        }
    }
}
